// Persistent storage of used slugs across runs (n8n's static data API)
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.usedSlugs)) data.usedSlugs = [];

// Normalize the queue regardless of how n8n's HTTP node returned it.
// Newer n8n splits JSON arrays into N items; older versions return a single item with the array in .json.
let queue;
const items = $input.all();
if (items.length > 1) {
  // Split case — each item is one topic
  queue = items.map((i) => i.json);
} else {
  // Single-item case — .json is either the array or a wrapper
  const first = items[0]?.json;
  if (Array.isArray(first)) queue = first;
  else if (Array.isArray(first?.data)) queue = first.data;
  else queue = [first];
}

if (!Array.isArray(queue) || queue.length === 0) {
  throw new Error('Topic queue is empty or not an array. Got: ' + JSON.stringify(queue).substring(0, 200));
}

const next = queue.find((t) => !data.usedSlugs.includes(t.slug));
if (!next) {
  throw new Error(`Topic queue exhausted (${queue.length} total, ${data.usedSlugs.length} already used). Add more topics to automation/topic-queue.json.`);
}

data.usedSlugs.push(next.slug);
return [{ json: next }];

// Defensive: handle wrapped, single-topic, OR full-queue-array input
let topic = $input.first().json;

// Unwrap up to 3 levels of { json: { ... } } wrapping (n8n version quirks)
for (let i = 0; i < 3; i++) {
  if (topic && typeof topic === 'object' && !Array.isArray(topic) && topic.json && !topic.slug) {
    topic = topic.json;
  } else {
    break;
  }
}

// If we got the full queue array, pick one
if (Array.isArray(topic)) {
  const data = $getWorkflowStaticData('global');
  if (!Array.isArray(data.usedSlugs)) data.usedSlugs = [];
  const next = topic.find((t) => !data.usedSlugs.includes(t.slug));
  if (!next) throw new Error('Topic queue exhausted (received as array of ' + topic.length + ', all ' + data.usedSlugs.length + ' already used).');
  data.usedSlugs.push(next.slug);
  topic = next;
}

if (!topic || typeof topic !== 'object' || Array.isArray(topic)) {
  throw new Error('Topic must be a single object. Got: ' + JSON.stringify(topic).substring(0, 300));
}
if (!topic.slug || !topic.title || !topic.primaryKeyword) {
  throw new Error('Topic missing required fields.\nslug: ' + topic.slug + '\ntitle: ' + topic.title + '\nprimaryKeyword: ' + topic.primaryKeyword + '\n\nAll keys: [' + Object.keys(topic).join(', ') + ']\n\nFull JSON (first 800 chars): ' + JSON.stringify(topic).substring(0, 800));
}

const ANTHROPIC_KEY = 'REPLACE_ANTHROPIC_KEY';
const today = new Date().toISOString().slice(0, 10);

const prompt = `You are writing a blog post for Cortisol+, an Apple Watch app that estimates cortisol from biometrics. Voice: evidence-first, no fluff, 8th-grade reading level, real science. Always include 'not medical advice; consult a healthcare provider' near the end. Cite real studies by author+year only if you are confident they exist — never invent citations.

Post spec:
- Title: ${topic.title}
- Primary keyword (must appear in title + first 100 words): ${topic.primaryKeyword}
- Angle: ${topic.angle}
- Length: 900-1200 words
- Format: MDX with YAML frontmatter
- Internal links to weave in: ${JSON.stringify(topic.internalLinks || [])}
- Target tool/quiz for this post: ${topic.targetTool}

# Required ending structure (do NOT skip)
Second-to-last section: a short paragraph recommending the related test, with link to ${topic.targetTool}. Example: 'Want to know where you stand? Take our 60-second cortisol quiz at ${topic.targetTool} — it scores your symptom pattern against the biomarkers above.'
Last section: soft Cortisol+ app CTA — 'Cortisol+ on Apple Watch tracks the relevant biomarker continuously, so you can see if this actually moves your trend.'
Final line: 'Not medical advice. Consult a healthcare provider for diagnosis or treatment.'

Return ONLY the MDX (no preamble, no code fences). Start with ---. Frontmatter required: title, description (140-160 chars w/ keyword), pubDate: ${today}, tags (3-5 from cortisol/stress/sleep/hrv/supplements/perimenopause/athletes/burnout/comparisons/wearables/food), draft: false, targetTool: ${topic.targetTool}. Structure: max 5 H2 sections, short paragraphs, at least one bulleted list.`;

// Call Claude API
const response = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'x-api-key': ANTHROPIC_KEY,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-5-20250929',
    max_tokens: 4096,
    messages: [{ role: 'user', content: prompt }]
  })
});

const claudeBody = await response.json();

if (!response.ok) {
  throw new Error('Claude API error (' + response.status + '): ' + JSON.stringify(claudeBody).substring(0, 500));
}

let mdx = claudeBody.content?.[0]?.text ?? '';

if (!mdx) {
  throw new Error('Claude returned empty content. Response: ' + JSON.stringify(claudeBody).substring(0, 500));
}

// Strip any accidental markdown code fences
mdx = mdx.replace(/^```(mdx|markdown)?\s*\n/, '').replace(/\n```\s*$/, '').trim();

// Validate the output
const errors = [];
if (!mdx.startsWith('---')) errors.push('Missing frontmatter');
if (!mdx.includes('\ntitle:')) errors.push('Missing title');
if (!mdx.includes('\ndescription:')) errors.push('Missing description');
if (!mdx.includes('\npubDate:')) errors.push('Missing pubDate');
if (!mdx.includes('draft: false')) errors.push('Missing/wrong draft flag');
if (!mdx.includes('targetTool:')) errors.push('Missing targetTool frontmatter field');
if (mdx.length < 3000) errors.push(`Too short (${mdx.length} chars)`);
if (mdx.length > 25000) errors.push(`Too long (${mdx.length} chars)`);
if (!mdx.toLowerCase().includes(topic.primaryKeyword.toLowerCase())) errors.push(`Missing keyword: ${topic.primaryKeyword}`);
if (!mdx.toLowerCase().includes('medical advice')) errors.push('Missing medical disclaimer');
if (!mdx.includes(topic.targetTool)) errors.push(`Body missing link to targetTool: ${topic.targetTool}`);
if (!mdx.toLowerCase().includes('cortisol+') && !mdx.toLowerCase().includes('apple watch')) errors.push('Missing Cortisol+ app mention');

if (errors.length) {
  throw new Error('Validation failed for ' + topic.slug + ':\n' + errors.join('\n') + '\n\nFirst 500 chars:\n' + mdx.substring(0, 500));
}

return [{
  json: {
    slug: topic.slug,
    title: topic.title,
    primaryKeyword: topic.primaryKeyword,
    mdx,
    base64Mdx: Buffer.from(mdx, 'utf-8').toString('base64'),
    path: `src/content/blog/${topic.slug}.mdx`,
    wordCount: mdx.split(/\s+/).length
  }
}];

